// Writes src/data/scope3Rules.ts from the ESG owner's two rule files (docs/adr/0015):
//
//   node scripts/scope3-rules-seed.ts <kontoregler.csv> <posteringsregler.csv>
//
// The CSV files themselves aren't committed (the posting rules carry the approver's initials).
// Review the diff of the generated file like any other change.

import { readFileSync, writeFileSync } from 'node:fs'
import { parseAccountRules, parsePostingRules } from '../src/calc/ruleSeed.ts'

const [accountsPath, postingsPath] = process.argv.slice(2)
if (!accountsPath || !postingsPath) {
  console.error('Usage: node scripts/scope3-rules-seed.ts <kontoregler.csv> <posteringsregler.csv>')
  process.exit(1)
}

const accountRules = parseAccountRules(readFileSync(accountsPath, 'utf8'))
const postingRules = parsePostingRules(readFileSync(postingsPath, 'utf8'))

const out = `// Generated by scripts/scope3-rules-seed.ts from the ESG owner's kontoregler.csv and
// posteringsregler.csv (docs/adr/0015). Don't edit by hand: regenerate from the files.

import type { AccountRule, PostingRule } from '../calc/spendRules'

export const accountRules: readonly AccountRule[] = [
${accountRules.map((r) => `  ${JSON.stringify(r)},`).join('\n')}
]

/** In priority order */
export const postingRules: readonly PostingRule[] = [
${postingRules.map((r) => `  ${JSON.stringify(r)},`).join('\n')}
]
`
writeFileSync(new URL('../src/data/scope3Rules.ts', import.meta.url), out)
console.log(`Wrote ${accountRules.length} account rules and ${postingRules.length} posting rules.`)
